inline bool Matches(const Span& span,const unsigned char* actual,std::uintptr_t base){
 unsigned char expected[32];std::memcpy(expected,span.bytes,32);
 for(auto at:span.reloc)if(at!=255){std::uint32_t value=0;std::memcpy(&value,expected+at,4);value+=static_cast<std::uint32_t>(base-0x400000u);std::memcpy(expected+at,&value,4);}
 return std::memcmp(actual,expected,32)==0;
}
